void dma_out_set_timer(int start_address, int dma_len, unsigned int timer) { 
    // set up input buffer to receive INPUT_BUF_START size
    CSR_WRITE(DMA_1_START_ADDR, start_address);
    CSR_WRITE(DMA_1_LENGTH, dma_len);
    CSR_WRITE(DMA_1_TIMER_VAL, timer);  // start right away
    CSR_WRITE(DMA_1_PUSH_SCHEDULE, 0); // any value
}


void dma_out_set_safe(unsigned int dma_ptr, unsigned int size, unsigned int timer) 
{ 
  unsigned int occupancy;
  // unsigned int occupancy_busy;
  // unsigned int occupancy_combined1, occupancy_combined2;
  while(1) 
  {
    CSR_READ(DMA_1_SCHEDULE_OCCUPANCY, occupancy);
    if(occupancy < DMA_1_SCHEDULE_DEPTH) 
     {
      break; // should break on first go
     } 
    else 
     {
      // stuck, can report this with ringbus
      // ring_block_send_eth(0xd0000000);
     }
  }
  dma_out_set_timer(dma_ptr, size, timer);
}


void main(void)
{
  
  unsigned int dma_out_address=VMEM_DMA_ADDRESS(input_coarse_sync);
  unsigned int dma_out_address_single;

  unsigned int timer_now;

  CSR_READ(TIMER_VALUE, timer_now);

  while(1) {
  	for(int index = 0; index < 10; index++) {

        // bump timer first (4 is the down rate)
        timer_now += DMA_OUT_SIZE * 4;

        dma_out_address_single = dma_out_address + (index*DMA_OUT_SIZE);

        dma_out_set_safe(dma_out_address_single, DMA_OUT_SIZE, timer_now);
  	}
  }



}  
  

